create extension if not exists pgcrypto;
create type public.user_role as enum ('customer','admin','manager'); create type public.stock_status as enum ('available','reserved','sold','coming_soon'); create type public.purchase_type as enum ('cash','online','credit','installment'); create type public.order_status as enum ('pending','confirmed','processing','completed','cancelled'); create type public.otp_purpose as enum ('login','order');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, phone text unique, full_name text, role public.user_role not null default 'customer', is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.brands (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, logo_url text, description text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.car_models (id uuid primary key default gen_random_uuid(), brand_id uuid not null references public.brands(id), name text not null, slug text not null unique, description text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.cars (id uuid primary key default gen_random_uuid(), brand_id uuid not null references public.brands(id), model_id uuid not null references public.car_models(id), name text not null, slug text not null unique, short_description text, description text, price numeric(14,2) not null check(price>=0), currency char(3) not null default 'UZS', old_price numeric(14,2) check(old_price is null or old_price>=0), year smallint not null check(year between 1900 and 2100), body_type text, fuel_type text, transmission text, drive_type text, engine_volume numeric(5,2), engine_power integer, range_km integer, seats smallint, color text, stock_status public.stock_status not null default 'coming_soon', is_featured boolean not null default false, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.car_images (id uuid primary key default gen_random_uuid(), car_id uuid not null references public.cars(id) on delete cascade, storage_path text not null unique, public_url text, alt_text text, sort_order integer not null default 0, is_primary boolean not null default false, created_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), order_number text not null unique, customer_id uuid not null references public.profiles(id), car_id uuid not null references public.cars(id), purchase_type public.purchase_type not null, status public.order_status not null default 'pending', total_amount numeric(14,2) not null check(total_amount>=0), currency char(3) not null default 'UZS', notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_status_history (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, old_status public.order_status, new_status public.order_status not null, changed_by uuid references public.profiles(id), note text, created_at timestamptz not null default now());
create table public.otp_verifications (id uuid primary key default gen_random_uuid(), phone text not null, code_hash text not null, purpose public.otp_purpose not null, attempts smallint not null default 0 check(attempts>=0), expires_at timestamptz not null, verified_at timestamptz, created_at timestamptz not null default now());
create table public.banks (id uuid primary key default gen_random_uuid(), name text not null, code text not null unique, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.credit_applications (id uuid primary key default gen_random_uuid(), order_id uuid not null unique references public.orders(id) on delete cascade, bank_id uuid not null references public.banks(id), external_application_id text, status text not null default 'pending', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}'::jsonb check(not (metadata ?| array['password','otp','code','passport','pinfl'])), created_at timestamptz not null default now());
create index profiles_phone_idx on public.profiles(phone); create index car_models_brand_id_idx on public.car_models(brand_id); create index cars_brand_id_idx on public.cars(brand_id); create index cars_model_id_idx on public.cars(model_id); create index cars_status_active_idx on public.cars(stock_status,is_active); create index car_images_car_id_idx on public.car_images(car_id); create unique index car_images_one_primary_idx on public.car_images(car_id) where is_primary; create index orders_customer_id_idx on public.orders(customer_id); create index orders_car_id_idx on public.orders(car_id); create index orders_status_idx on public.orders(status); create index order_history_order_id_idx on public.order_status_history(order_id); create index otp_phone_idx on public.otp_verifications(phone); create index credit_bank_idx on public.credit_applications(bank_id); create index audit_actor_idx on public.audit_logs(actor_id);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
create trigger profiles_updated_at before update on public.profiles for each row execute procedure public.set_updated_at(); create trigger brands_updated_at before update on public.brands for each row execute procedure public.set_updated_at(); create trigger models_updated_at before update on public.car_models for each row execute procedure public.set_updated_at(); create trigger cars_updated_at before update on public.cars for each row execute procedure public.set_updated_at(); create trigger orders_updated_at before update on public.orders for each row execute procedure public.set_updated_at(); create trigger banks_updated_at before update on public.banks for each row execute procedure public.set_updated_at(); create trigger credit_updated_at before update on public.credit_applications for each row execute procedure public.set_updated_at();
alter table public.profiles enable row level security; alter table public.brands enable row level security; alter table public.car_models enable row level security; alter table public.cars enable row level security; alter table public.car_images enable row level security; alter table public.orders enable row level security; alter table public.order_status_history enable row level security; alter table public.otp_verifications enable row level security; alter table public.banks enable row level security; alter table public.credit_applications enable row level security; alter table public.audit_logs enable row level security;
create policy "public active brands" on public.brands for select using (is_active); create policy "public active models" on public.car_models for select using (is_active); create policy "public active cars" on public.cars for select using (is_active); create policy "public images" on public.car_images for select using (true); create policy "own profile read" on public.profiles for select using (auth.uid()=id); create policy "own profile update" on public.profiles for update using (auth.uid()=id) with check(auth.uid()=id); create policy "own orders" on public.orders for select using(auth.uid()=customer_id); create policy "own history" on public.order_status_history for select using(exists(select 1 from public.orders o where o.id=order_id and o.customer_id=auth.uid())); create policy "own credit" on public.credit_applications for select using(exists(select 1 from public.orders o where o.id=order_id and o.customer_id=auth.uid()));
insert into storage.buckets(id,name,public) values('car-images','car-images',true) on conflict do nothing; create policy "public car image objects" on storage.objects for select using(bucket_id='car-images');
